package chart

// Phase 4.9 parity regression: the Go engine must reproduce the shared
// Python↔Go fixture exactly (display literal H/L + pack raw corrections,
// overlay near-date dedup, canonical cumulative factors). The fixture is
// generated by dev/test_phase49_correction_parity_v1.py --emit and verified
// there as well, so both engines are pinned to one golden file.

import (
	"encoding/json"
	"math"
	"os"
	"path/filepath"
	"testing"
)

type p49Event struct {
	Date   string  `json:"date"`
	Ratio  float64 `json:"ratio"`
	Source string  `json:"source"`
}

type p49Fixture struct {
	InsCode string           `json:"ins_code"`
	Symbol  string           `json:"symbol"`
	Candles []map[string]any `json:"candles"`
	Events  []p49Event       `json:"events"`
	Expected struct {
		DisplayCandles   []map[string]any `json:"display_candles"`
		KeptEvents       []p49Event       `json:"kept_events"`
		SuppressedEvents []map[string]any `json:"suppressed_events"`
		Factors          []struct {
			Time   string  `json:"time"`
			Factor float64 `json:"factor"`
		} `json:"factors"`
		ChainAnchoredLast bool             `json:"chain_anchored_last"`
		ChainComplete     bool             `json:"chain_complete"`
		NearDeduped       []map[string]any `json:"near_deduped"`
	} `json:"expected"`
}

func loadP49Fixture(t *testing.T) p49Fixture {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "phase49", "fixture.json"))
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var fx p49Fixture
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatalf("parse fixture: %v", err)
	}
	return fx
}

func num(v any) float64 {
	switch x := v.(type) {
	case float64:
		return x
	case int:
		return float64(x)
	case json.Number:
		f, _ := x.Float64()
		return f
	}
	return math.NaN()
}

func TestPhase49ParityFixture(t *testing.T) {
	pack := loadPackFromDir(filepath.Join("testdata", "phase49", "pack"))
	if pack == nil {
		t.Fatal("test pack did not load")
	}
	if pack.Mode != "overlay" {
		t.Fatalf("test pack mode = %q, want overlay", pack.Mode)
	}
	fx := loadP49Fixture(t)

	// 1) display pipeline: literal H/L, then versioned raw corrections.
	gotDisplay := literalDisplayCandles(pack, fx.InsCode, fx.Symbol, fx.Candles)
	byTime := map[string]map[string]any{}
	for _, c := range gotDisplay {
		byTime[stringValue(c["time"])] = c
	}
	for _, want := range fx.Expected.DisplayCandles {
		have, ok := byTime[stringValue(want["time"])]
		if !ok {
			t.Fatalf("display candle %v missing", want["time"])
		}
		for k, wv := range want {
			hv, present := have[k]
			if !present {
				t.Fatalf("display %v.%s missing", want["time"], k)
			}
			switch w := wv.(type) {
			case float64:
				if math.Abs(num(hv)-w) > 1e-9 {
					t.Fatalf("display %v.%s = %v, want %v", want["time"], k, hv, w)
				}
			case string:
				if stringValue(hv) != w {
					t.Fatalf("display %v.%s = %v, want %v", want["time"], k, hv, w)
				}
			}
		}
	}

	// 2) overlay chain: exact pack dates suppressed, near-date same-action dedup,
	//    conflicting near-date event kept.
	events := make([]canonEvent, 0, len(fx.Events))
	for _, e := range fx.Events {
		events = append(events, canonEvent{Date: e.Date, Ratio: e.Ratio, Source: e.Source})
	}
	kept, suppressed, meta := pack.ApplyFactorEvents(fx.InsCode, fx.Symbol, events)
	if len(kept) != len(fx.Expected.KeptEvents) {
		t.Fatalf("kept=%d, want %d: %+v", len(kept), len(fx.Expected.KeptEvents), kept)
	}
	for i, want := range fx.Expected.KeptEvents {
		if kept[i].Date != want.Date || math.Abs(kept[i].Ratio-want.Ratio) > 1e-12 {
			t.Fatalf("kept[%d] = %s/%v, want %s/%v", i, kept[i].Date, kept[i].Ratio,
				want.Date, want.Ratio)
		}
	}
	foundDedupe := false
	for _, e := range suppressed {
		if e.Date == "2025-06-09" {
			if d, ok := e.Extra["dedupe"]; ok {
				m, _ := d.(map[string]any)
				if m["reason"] == "same-action-near-pack-step" &&
					stringValue(m["pack_date"]) == "2025-06-10" {
					foundDedupe = true
				}
			}
		}
	}
	if !foundDedupe {
		t.Fatalf("near-date suppressed event lacks dedupe evidence: %+v", suppressed)
	}
	if n, _ := meta["near_deduped_count"].(int); n != 1 {
		t.Fatalf("near_deduped_count = %v, want 1 (meta=%+v)", meta["near_deduped_count"], meta)
	}

	// 3) canonical cumulative factors must equal the Python golden values.
	_, _, chainEvents, _ := engineEvents(kept)
	times := make([]string, 0, len(fx.Candles))
	for _, c := range fx.Candles {
		times = append(times, stringValue(c["time"]))
	}
	factors, chain := chainFactors(times, chainEvents)
	if anchored, _ := chain["anchored_last"].(bool); !anchored {
		t.Fatalf("chain not anchored at last candle: %+v", chain)
	}
	for i, want := range fx.Expected.Factors {
		if stringValue(fx.Candles[i]["time"]) != want.Time {
			t.Fatalf("fixture time mismatch at %d", i)
		}
		if math.Abs(factors[i]-want.Factor) > 1e-9 {
			t.Fatalf("factor[%s] = %.12g, want %.12g", want.Time, factors[i], want.Factor)
		}
	}
}
